    async def generate(
        self,
        quest_id,
        *,
        expected_version,
        provider,
        model_id,
        provider_id,
        capabilities,
        capability_sources,
        source_event_id=None,
        source_event_token=None,
        context_limit=32768,
        output_limit=4096,
    ):
        quest = self.store.get_quest(quest_id)
        if quest is None:
            raise KeyError(quest_id)
        if quest["version"] != expected_version:
            raise QuestVersionConflict("Quest version conflict")
        content = _canonical(
            {
                "title": quest["title"],
                "goal": quest["goal"],
                "plan_revision": quest["plan_revision"],
                "available_tools": _tool_catalogue(),
                "capability_names": list(CAPABILITY_NAMES),
                "limits": _planning_limits(),
            }
        )
        if len(content.encode("utf-8")) > 16000:
            raise DomainError("Quest is too large to plan")
        schema = GraphWire.model_json_schema()
        from .providers import schema_format_instruction

        if type(context_limit) is not int or type(output_limit) is not int or output_limit < 1:
            raise DomainError("Invalid planner budget")
        instruction = schema_format_instruction(schema)
        if (
            len(_canonical({"content": content, "schema": schema}).encode("utf-8"))
            + len(_canonical({"role": "system", "content": instruction}).encode("utf-8"))
            + output_limit
            + 2048
            > context_limit
        ):
            raise DomainError("Planner context budget exceeded")
        from .domain import new_id
        from .runtime import ModelCallContext

        messages = [
            {"role": "system", "content": _PLANNER_POLICY},
            {"role": "user", "content": content},
        ]
        response = None
        failure = None
        # One bounded repair round: a rejected proposal is shown its concrete
        # contract violation and may be corrected once. No unbounded retry.
        for attempt in range(2):
            if attempt:
                repair = _canonical(
                    {
                        "rejected_proposal_error": failure,
                        "required_action": (
                            "Return a corrected DAG. allowed_tools must be names from "
                            "available_tools; required_capabilities names must be from "
                            "capability_names; every node needs 1-5 verifiable success "
                            "criteria; node budget_tokens must sum to max_total_tokens or less."
                        ),
                        "validation_hint": "value_error means a Core contract rejected the value",
                    }
                )
                if (
                    len(_canonical({"content": content + repair, "schema": schema}).encode("utf-8"))
                    + len(_canonical({"role": "system", "content": instruction}).encode("utf-8"))
                    + output_limit
                    + 2048
                    > context_limit
                ):
                    raise DomainError("Planner repair budget exceeded") from None
                messages = [
                    {"role": "system", "content": _PLANNER_POLICY},
                    {"role": "user", "content": content},
                    {"role": "assistant", "content": (response.text or "")[:8000]},
                    {"role": "user", "content": repair},
                ]
            request = ModelRequest(
                model_id=model_id,
                provider_id=provider_id,
                messages=messages,
                response_format={
                    "type": "json_schema",
                    "json_schema": {"name": "quest_graph", "strict": True, "schema": schema},
                },
                max_output_tokens=output_limit,
                context_limit=context_limit,
                model_capabilities=capabilities,
                model_capability_sources=capability_sources,
                budget_context=ModelCallContext(
                    call_id=new_id("call"),
                    purpose="planner",
                    workspace_id=self.store.workspace.id,
                    quest_id=quest_id,
                ),
            )
            response = await provider.generate(request)
            if getattr(response, "finish_reason", None) not in {None, "stop", "mock"} or len(
                response.text.encode("utf-8")
            ) > min(128000, output_limit * 8):
                failure = ["incomplete_graph_proposal"]
                continue
            try:
                data = GraphWire.model_validate_json(response.text).proposal().model_dump()
            except (ValueError, TypeError, ValidationError) as exc:
                failure = _validation_digest(exc)
                continue
            return self.propose(
                quest_id,
                data,
                expected_version=expected_version,
                source_event_id=source_event_id,
                source_event_token=REDACTED,
            )
        raise DomainError("Invalid graph proposal") from (
            ValueError(failure) if isinstance(failure, str) else None
        )

