            for item in (execution.get("tools") or [])[:1000]
        ],
        "workers": [
            {
                **_pick(
                    item,
                    (
                        "id",
                        "worker_id",
                        "node_key",
                        "role_id",
                        "provider_id",
                        "model_id",

                    + (self.retry_seconds if retry_delay is None else retry_delay),
