        with self.store.connection() as connection:
            connection.execute("BEGIN")
            quest = connection.execute("SELECT * FROM quests WHERE id=?", (quest_id,)).fetchone()
            if quest is None:
                raise KeyError(quest_id)
            plan = connection.execute(
                "SELECT * FROM quest_plans WHERE quest_id=? AND revision=? AND status='approved'",
                (quest_id, quest["plan_revision"]),
            ).fetchone()
def _review_assignment(store, connection, run, *, preview=False):
    """Read the approved sources shared by review and running capacity observations."""
    quest = connection.execute("SELECT * FROM quests WHERE id=?", (run["quest_id"],)).fetchone()
    plan = connection.execute("SELECT * FROM quest_plans WHERE id=?", (run["plan_id"],)).fetchone()
    node = connection.execute(
        "SELECT * FROM task_nodes WHERE plan_id=? AND node_key=?", (run["plan_id"], run["node_key"])
    ).fetchone()
    if (
        quest is None
        or plan is None
        or node is None
        or quest["plan_revision"] != run["plan_revision"]
        or plan["revision"] != run["plan_revision"]
        or plan["digest"] != run["plan_digest"]
        or plan["status"] != "approved"
        or node["worker_id"] != run["worker_id"]
        or run["state"] not in ({"running"} if preview else {"review_pending", "succeeded"})
        or node["status"] != run["state"]
        or (preview and quest["status"] != "running")
        or (run["state"] == "review_pending" and quest["status"] != "running")
        or (
            run["state"] == "succeeded"
            and quest["status"] not in {"running", "reviewing", "completed"}
        )
    ):
        raise DomainError("Independent review assignment changed")
    authority = TeamCompositionService(store)
    team = (
        authority.get_approved(
            run["quest_id"], run["plan_revision"], run["team_digest"], connection=connection
        )
        if preview
        else authority.get_historical_approved(
            run["quest_id"],
            run["plan_revision"],
            run["team_digest"],
            connection=connection,
            run_id=run["id"],
        )
    )
    member = team["members"][run["member_index"]]
    if (member["task_node_key"], member["role_id"], member["provider_id"], member["model_id"]) != (
        run["node_key"],
        run["role_id"],
        run["provider_id"],
        run["model_id"],
    ):
        raise DomainError("Independent review model is not approved")
    criteria = json.loads(node["criteria_json"])
    selected = review_criteria(criteria)
    if not selected:
        raise DomainError("Independent review was not authorized by this plan")
    metadata = json.loads(quest["metadata"])
    source_id = metadata.get("original_request_message_id")
    source = (
        connection.execute(
            "SELECT id,content FROM messages WHERE id=? AND role='user' AND conversation_id=?",
            (source_id, quest["conversation_id"]),
        ).fetchone()
        if source_id
        else None
    )
    if source_id and (
        source is None
        or hashlib.sha256(source["content"].encode("utf-8")).hexdigest()
        != metadata.get("original_request_sha256")
    ):
        raise DomainError("Original user contract failed integrity validation")
    update_id = metadata.get("goal_update_message_id")
    update = (
        connection.execute(
            "SELECT id,content FROM messages WHERE id=? AND role='user' AND conversation_id=?",
            (update_id, quest["conversation_id"]),
        ).fetchone()
        if update_id
        else None
    )
    if update_id and (
        update is None
        or hashlib.sha256(update["content"].encode("utf-8")).hexdigest()
        != metadata.get("goal_update_sha256")
    ):
        raise DomainError("Updated user contract failed integrity validation")
    from .constraints import ConstraintService

    constraint_context = ConstraintService(store).context(
        quest_id=run["quest_id"], limit=16, max_bytes=8000, connection=connection
    )
    return quest, node, member, criteria, selected, metadata, source, update, constraint_context


def _packet(store, connection, run, *, parse_diagnostics=False):
    """Build a bounded reproducible observation; record provenance, not claim truth."""
    assignment = _review_assignment(store, connection, run)

"""Verified completed-node lineage across separately approved remaining DAGs."""

import hashlib
import json

from .domain import DomainError


def canonical(value):
    return json.dumps(value, sort_keys=True, ensure_ascii=False, separators=(",", ":"))


def digest(value):
    return hashlib.sha256(canonical(value).encode()).hexdigest()


def request_binding(quest):
    metadata = json.loads(quest["metadata"]) if isinstance(quest["metadata"], str) else quest["metadata"]
    return {key: metadata.get(key) for key in ("original_request_message_id", "original_request_sha256",
        "goal_update_message_id", "goal_update_sha256")}


def _graph(plan):
    graph = json.loads(plan["graph_json"])
    if digest(graph) != plan["digest"]:
        raise DomainError("Lineage plan content digest mismatch")
    return graph


def _source(connection, quest, newplan, node_key, *, require_approved):
    graph = _graph(newplan)
    lineage = graph.get("revision_lineage")
    if not isinstance(lineage, dict) or lineage.get("version") != "remaining-dag-v1":
        raise DomainError("Completed revision lineage unavailable")
    if require_approved and (newplan["status"] != "approved" or quest["plan_revision"] != newplan["revision"]):
        raise DomainError("Current approved revision lineage required")
    if lineage.get("quest_goal_sha256") != hashlib.sha256(quest["goal"].encode()).hexdigest() or lineage.get("request_binding") != request_binding(quest):
        raise DomainError("Lineage original goal/source binding changed")
    entries = [item for item in lineage.get("completed_nodes", []) if item.get("node_key") == node_key]
    if len(entries) != 1:
        raise DomainError("Completed lineage identity is ambiguous")
    entry = entries[0]
    source_plan = connection.execute("SELECT * FROM quest_plans WHERE id=? AND quest_id=?", (entry["source_plan_id"], quest["id"])).fetchone()
    if source_plan is None or source_plan["revision"] != entry["source_revision"] or source_plan["digest"] != entry["source_plan_digest"] or not source_plan["approved_at"] or source_plan["approved_by"] != "local_user":
        raise DomainError("Completed lineage source approval is invalid")
    source_graph = _graph(source_plan)
    old_nodes = [item for item in source_graph["nodes"] if item["key"] == node_key]
    new_nodes = [item for item in graph["nodes"] if item["key"] == node_key]
    if len(old_nodes) != 1 or len(new_nodes) != 1 or old_nodes[0] != new_nodes[0] or digest(old_nodes[0]) != entry["contract_sha256"]:
        raise DomainError("Completed lineage node contract changed")
    source_node = connection.execute("SELECT * FROM task_nodes WHERE plan_id=? AND node_key=?", (source_plan["id"], node_key)).fetchone()
    source_run = connection.execute("SELECT * FROM worker_runs WHERE id=? AND quest_id=?", (entry["run_id"], quest["id"])).fetchone()
    new_node = connection.execute("SELECT * FROM task_nodes WHERE plan_id=? AND node_key=?", (newplan["id"], node_key)).fetchone()
    if source_node is None or source_run is None or source_node["status"] != "succeeded" or source_run["state"] != "succeeded" or source_run["plan_id"] != source_plan["id"] or source_run["node_key"] != node_key or source_run["plan_digest"] != source_plan["digest"] or source_run["plan_revision"] != source_plan["revision"] or source_node["worker_id"] != entry["worker_id"] or source_run["worker_id"] != entry["worker_id"] or json.loads(source_node["evidence_refs"]) != entry["evidence_refs"]:
        raise DomainError("Completed lineage source run/evidence changed")
    if new_node is not None and (new_node["status"] != "succeeded" or new_node["worker_id"] != entry["worker_id"] or json.loads(new_node["evidence_refs"]) != entry["evidence_refs"]):
        raise DomainError("Completed lineage target state differs from its source")
    # Every link must be a real user-approved successor of the declared parent.
    cursor, seen = newplan, set()
    while cursor["id"] != source_plan["id"]:
        if cursor["id"] in seen or len(seen) >= 8:
            raise DomainError("Completed lineage chain exceeded its bound")
        seen.add(cursor["id"])
        current = _graph(cursor).get("revision_lineage")
        if not isinstance(current, dict):
            raise DomainError("Completed lineage chain is broken")
        parent = connection.execute("SELECT * FROM quest_plans WHERE id=? AND quest_id=?", (current["parent_plan_id"], quest["id"])).fetchone()
        if parent is None or parent["digest"] != current["parent_digest"] or parent["revision"] != current["parent_revision"] or parent["revision"] >= cursor["revision"] or not parent["approved_at"]:
            raise DomainError("Completed lineage parent approval changed")
        cursor = parent
    return {"source_plan": dict(source_plan), "source_node": dict(source_node), "source_run": dict(source_run), "entry": entry}


def validated_lineage_source(connection, quest, newplan, node_key):
    return _source(connection, quest, newplan, node_key, require_approved=True)


def validate_pending_lineage(connection, quest, newplan):
    graph = _graph(newplan)
    lineage = graph["revision_lineage"]
    if quest["plan_revision"] != lineage["parent_revision"]:
        raise DomainError("Remaining DAG parent revision changed")
    for entry in lineage["completed_nodes"]:
        _source(connection, quest, newplan, entry["node_key"], require_approved=False)
    return lineage

"""Worker-side enforcement of explicitly approved review-cycle contracts."""

import hashlib
import json
from pathlib import Path

from .domain import DomainError
from .review_envelope import review_cycle_state, validate_review_envelope


def canonical(value):
    return json.dumps(
        value, sort_keys=True, ensure_ascii=False, separators=(",", ":"), allow_nan=False
    )


def cycle_allowance(connection, run, envelope):
    state = review_cycle_state(connection, run["id"], envelope)
    held = state["future_reserve_tokens"]
    if state["correction_started"]:
        if not state["correction_calls_remaining"]:
            raise DomainError("Approved correction call count exhausted")
        held -= envelope["correction_input_tokens"] + envelope["correction_output_tokens"]
    return {
        **state,
        "held_after_current_request": held,
        "current_request_allowance": max(0, run["token_limit"] - run["token_spent"] - held),
    }


def verify_worker_envelope(store, member):
    envelope = member.get("review_envelope")
    if envelope is None:
        return None
    from .capacity_preflight import verify_input_inventory

    envelope = validate_review_envelope(envelope)
    if not isinstance(member.get("required_input_paths"), list):
        raise DomainError("Approved review envelope lacks declared inputs")
    verify_input_inventory(store, member["verified_input_inventory"])
    return envelope


def validate_capsule_binding(connection, run, member):
    if member.get("review_envelope") is None:
        return
    row = connection.execute(
        "SELECT capsule_json FROM worker_capsules WHERE run_id=?", (run["id"],)
    ).fetchone()
    if row is None:
        raise DomainError("Approved review contract has no Worker capsule")
    capsule = json.loads(row[0])
    if any(
        capsule.get(key) != member.get(key)
        for key in ("review_envelope", "required_input_paths", "verified_input_inventory")
    ):
        raise DomainError("Worker review contract differs from the approved team")


def verify_read_identity(store, connection, run, path, data):
    """Recheck source identity at the actual read, after approval and queuing."""
    from .team_composition import TeamCompositionService

    team = TeamCompositionService(store).get_approved(
        run["quest_id"], run["plan_revision"], run["team_digest"], connection=connection
    )
    member = team["members"][run["member_index"]]
    if member.get("review_envelope") is None:
        return
    known = {
        str(Path(store.workspace.root) / item["path"]): item
        for item in member["verified_input_inventory"]
    }
    source = known.get(str(path))
    if source is not None and (
        len(data) != source["bytes"] or hashlib.sha256(data).hexdigest() != source["sha256"]
    ):
        raise DomainError("Approved source identity changed before the read")


def validate_batch(store, connection, run, capsule, calls):
    """Reject unbounded reads/writes before a pending call or side effect exists.

    This is a conservative admission policy for new contracts. Review reconstructs
    and validates the complete actual packet independently after delivery.
    """
    envelope = capsule.get("review_envelope")
    if envelope is None:
        return
    validate_review_envelope(envelope)
    from .tool_engine import ToolEngine

    service = ToolEngine(store)
    declared = {
        service._scope("file_read", {"path": path}) for path in capsule["required_input_paths"]
    }
    receipts = []
    artifacts = {}
    for row in connection.execute(
        "SELECT r.id,r.result_json,i.tool_name,i.resource_scope,r.result_digest,r.execution_mode "
        "FROM action_receipts r JOIN action_intents i ON i.id=r.intent_id "
        "WHERE i.run_id=? AND i.state='succeeded' ORDER BY r.rowid",
        (run["id"],),
    ):
        output = json.loads(row["result_json"])
        receipts.append(
            {
                key: row[key]
                for key in ("id", "tool_name", "resource_scope", "result_digest", "execution_mode")
            }
            | {"output": output}
        )
        if row["tool_name"] in {"file_write", "file_revise"}:
            artifacts[row["resource_scope"]] = None
    for path in artifacts:
        content = Path(path).read_text(encoding="utf-8")
        try:
            artifacts[path] = json.loads(content)
        except ValueError:
            artifacts[path] = content
    for call in calls:
        name, args = call["name"], call["arguments"]
        if name not in {"file_read", "file_write", "file_revise"}:
            continue
        path = service._scope(name, args)
        if name == "file_read":
            if path not in declared and path not in artifacts:
                raise DomainError(
                    "Read is outside the approved input inventory and owned artifacts"
                )
            data = Path(path).read_bytes()
            if len(data) > 65536:
                raise DomainError("Declared input exceeds bounded read contract")
            output = {"content": data.decode("utf-8"), "sha256": hashlib.sha256(data).hexdigest()}
        else:
            text = args.get("content")
            if not isinstance(text, str):
                raise DomainError("Artifact content must be UTF-8 text")
            try:
                artifacts[path] = json.loads(text)
            except ValueError:
                artifacts[path] = text
            output = {
                "path": path,
                "sha256": hashlib.sha256(text.encode()).hexdigest(),
                "bytes": len(text.encode()),
            }
            if name == "file_revise":
                output.update(
                    prior_receipt_id=args.get("prior_receipt_id"),
                    prior_sha256=args.get("expected_sha256"),
                )
        receipts.append(
            {
                "id": "receipt_" + "0" * 32,
                "tool_name": name,
                "resource_scope": path,
                "result_digest": "0" * 64,
                "execution_mode": run["execution_mode"],
                "output": output,
            }
        )
    if len(canonical(receipts).encode()) > envelope["max_source_bytes"]:
        raise DomainError("Tool batch would exceed approved complete source-receipt bytes")
    if (
        sum(len(canonical(value).encode()) for value in artifacts.values())
        > envelope["max_artifact_bytes"]
    ):
        raise DomainError("Tool batch would exceed approved complete artifact bytes")


def validate_delivery(capsule, value):
    envelope = capsule.get("review_envelope")
    if envelope is not None and len(canonical(value).encode()) > envelope["max_delivery_bytes"]:
        raise ValueError("Complete delivery exceeds its explicitly approved byte bound")

