    def start(self):
        self.thread.start()

    def stop(self):
        self.stop_event.set()
        self.thread.join(timeout=3)
        return {
            "samples": self.count,
            "errors": self.errors,
            "thread_stopped": not self.thread.is_alive(),
        }

