        rows = []
        for item in node["candidates"]:
            bounds = item["declared_bounds"]
            rows.append([
                item["profile_id"], bounds["max_artifact_bytes"], bounds["max_delivery_bytes"],
                item["action_evidence_allowance_bytes"], item["known_source_bytes"],
