                item["initial_work_tokens"], item["review_cycle_reserve_tokens"],
                item["minimum_node_tokens"], item["policy_cycle_calls"], item["violations"],
            ])
        nodes.append({"node": node["node"], "status": "available", "rows": rows, "omitted_candidates": node["omitted_candidates"], "unmeasurable_candidates": node["unmeasurable_candidates"]})
