}

/// Renders the window prefix and ordinary context with their comparison baseline.
pub(crate) async fn build_compaction_replacement_history(
 sess: &Session,
 step_context: &StepContext,
 world_state: &WorldState,
 compacted_history: Vec<ResponseItemEnvelope>,
) -> (Vec<ResponseItemEnvelope>, WorldStateSnapshot) {
 let (updates, snapshot) = sess
 .build_initial_context_with_world_state(step_context, world_state)
 .await;
 let (prefix, context) = split_prefix_updates(updates);
 let context = merge_world_state_updates(context);
 (
 assemble_compaction_history(compacted_history, prefix, context),
 snapshot,
 )
}

fn assemble_compaction_history(
 compacted_history: Vec<ResponseItemEnvelope>,
 prefix: Vec<ResponseItem>,
 context: Vec<ResponseItem>,
) -> Vec<ResponseItemEnvelope> {
 let history = insert_initial_context_before_last_real_user_or_summary(
 compacted_history,
 context.into_iter().map(ResponseItemEnvelope::new).collect(),
 );
 prefix
 .into_iter()
 .map(ResponseItemEnvelope::new)
 .chain(history)
 .collect()
}

pub(crate) async fn run_inline_auto_compact_task(
 sess: Arc<Session>,
 step_context: Arc<StepContext>,
 replacement_step_context: Arc<StepContext>,
 world_state: Arc<WorldState>,
 reason: CompactionReason,
 phase: CompactionPhase,
) -> CodexResult<bool> {
 let prompt = step_context
 .turn
 .config
 .compact_prompt
 .as_deref()
 .unwrap_or(SUMMARIZATION_PROMPT)
 .to_string();
 let input = vec![UserInput::Text {
 text: prompt,
 // Compaction prompt is synthesized; no UI element ranges to preserve.
 text_elements: Vec::new(),
 }];

 run_compact_task_inner(
 sess,
 step_context,
 replacement_step_context,
 input,
 world_state,
 CompactionTurnMetadata::new(
 CompactionTrigger::Auto,
 reason,
 CompactionImplementation::Responses,
 phase,
 ),
 )
 .await
}

pub(crate) async fn run_compact_task(
 sess: Arc<Session>,
 step_context: Arc<StepContext>,
 world_state: Arc<WorldState>,
 input: Vec<UserInput>,
) -> CodexResult<()> {
 run_compact_task_inner(
 sess.clone(),
 Arc::clone(&step_context),
 step_context,
 input,
 world_state,
 CompactionTurnMetadata::new(
 CompactionTrigger::Manual,
 CompactionReason::UserRequested,
 CompactionImplementation::Responses,
 CompactionPhase::StandaloneTurn,
 ),
 )
 .await?;
 Ok(())
}

async fn run_compact_task_inner(
 sess: Arc<Session>,
 step_context: Arc<StepContext>,
 replacement_step_context: Arc<StepContext>,
 input: Vec<UserInput>,
 world_state: Arc<WorldState>,
 compaction_metadata: CompactionTurnMetadata,
) -> CodexResult<bool> {
 let turn_context = Arc::clone(&step_context.turn);
 let trigger = compaction_metadata.trigger();
 let reason = compaction_metadata.reason();
 let phase = compaction_metadata.phase();
 let attempt = CompactionAnalyticsAttempt::begin(
 sess.as_ref(),
 turn_context.as_ref(),
 trigger,
 reason,
 CompactionImplementation::Responses,
 phase,
 )
 .await;
 let pre_compact_outcome = run_pre_compact_hooks(&sess, &turn_context, trigger).await;
 match pre_compact_outcome {
 PreCompactHookOutcome::Continue => {}
 PreCompactHookOutcome::Stopped => {
 let error = CodexErr::TurnAborted;
 attempt
 .track(
 sess.as_ref(),
 CompactionStatus::Interrupted,
 Some(&error),
 CompactionAnalyticsDetails::default(),
 )
 .await;
 return Err(error);
 }
 }
 let result = run_compact_task_inner_impl(
 Arc::clone(&sess),
 step_context,
 replacement_step_context,
 input,
 world_state,
 compaction_metadata,
 )
 .await;
 let status = compaction_status_from_result(&result);
 let codex_error = result.as_ref().err();
 if result.is_ok() {
 let post_compact_outcome = run_post_compact_hooks(&sess, &turn_context, trigger).await;
 if let PostCompactHookOutcome::Stopped = post_compact_outcome {
 attempt
 .track(
 sess.as_ref(),
 status,
 codex_error,
 CompactionAnalyticsDetails::default(),
 )
 .await;
 return Err(CodexErr::TurnAborted);
 }
 }
 attempt
 .track(
 sess.as_ref(),
 status,
 codex_error,
 CompactionAnalyticsDetails::default(),
 )
 .await;
 // Keep an installed checkpoint and its analytics. An inline stop hands control
 // back to the root if the deadline permits its final answer.
 let result = sess.finish_compaction(&turn_context, phase, result.map(|_| true));
 if let Err(err) = &result
 && !matches!(phase, CompactionPhase::PostTurn)
 && !matches!(err.details(), CodexErrorDetails::Interrupted)
 && !crate::tasks::ends_turn_as_interrupted(err)
 {
 sess.track_turn_codex_error(turn_context.as_ref(), err);
 // Pre-turn failures are reported after preserving the incoming prompt.
 if !matches!(phase, CompactionPhase::PreTurn) {
 let event = EventMsg::Error(err.to_error_event(/*message_prefix*/ None));
 sess.send_event(&turn_context, event).await;
 }
 }
 result
}

