"""New audit mode rejects protocol tampering and independently decodes raw sources."""

import asyncio
import copy
import importlib.util
import json
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[2]
sys.path[:0] = [str(ROOT / "backend/src"), str(ROOT / "backend/tests")]
spec = importlib.util.spec_from_file_location("usage_v29_test", Path(__file__).with_name("audit_live_usage_v29.py"))
audit = importlib.util.module_from_spec(spec)
spec.loader.exec_module(audit)

import test_audit_live_usage_v23 as prior
from test_core_source_prefetch_v23 import prepared
from forge_core.source_wire import RAW_TEXT_FORMAT, encode_source_text


def record():
    return {
        "scenario": {"limits": {}, "token_budget_policy": {
            "mode": "disabled_by_user", "enforced": False,
            "protocol_change": "user_cancelled_cumulative_token_cap",
            "usage_accounting": "all_model_attempts_must_have_known_settled_usage",
        }},
        "runtime_settings": {"token_budgets_enforced": False, "model_token_limit": None},
        "results": {"budget": {"token_budgets_enforced": False, "token_limit": None}},
    }


@pytest.mark.parametrize("fault", ["none", "missing_limit", "api_true", "zero", "scenario_cap", "unknown_policy", "runtime_true"])
def test_disabled_mode_requires_the_entire_explicit_binding(fault):
    value = record()
    if fault == "missing_limit":
        del value["results"]["budget"]["token_limit"]
    elif fault == "api_true":
        value["results"]["budget"]["token_budgets_enforced"] = True
    elif fault == "zero":
        value["runtime_settings"]["model_token_limit"] = 0
    elif fault == "scenario_cap":
        value["scenario"]["limits"]["max_total_tokens"] = 1000000000
    elif fault == "unknown_policy":
        value["scenario"]["token_budget_policy"]["protocol_change"] = "unknown"
    elif fault == "runtime_true":
        value["runtime_settings"]["token_budgets_enforced"] = True
    assert audit.disabled_token_policy(value) is (fault == "none")


@pytest.mark.parametrize("fault", ["none", "trailing", "hash", "length", "format", "unreferenced"])
def test_independent_raw_decoder_checks_full_original_spans(fault):
    packet = {"origin": "core-declared-source-prefetch-v1", "sources": [{"output": "原\r\n\"\\text" * 100}]}
    content = encode_source_text(packet)
    if fault == "trailing":
        content += "extra"
    elif fault != "none":
        end = content.index("\n", len(audit.RAW_INTRO))
        header = json.loads(content[len(audit.RAW_INTRO):end])
        if fault == "hash":
            header["texts"][0]["sha256"] = "0" * 64
        elif fault == "length":
            header["texts"][0]["chars"] += 1
        elif fault == "format":
            header["format"] = "unknown"
        else:
            header["view"]["packet"] = {}
        content = audit.RAW_INTRO + json.dumps(header) + content[end:]
    if fault == "none":
        assert audit.decode_raw_sources(content) == packet
    else:
        with pytest.raises((ValueError, IndexError)):
