def model_checkpoint_audit(connection, compaction):
    """Bind a recorded stopped-Core model checkpoint to actual SQL call evidence."""
    if not compaction:
        return {"applicable": False, "passed": True, "checkpoints": []}
    errors, details, identities, source_ids = [], [], set(), []
    checkpoints = compaction.get("model_checkpoints")
    if compaction.get("compaction_mode") != "model_gateway_handoff" or compaction.get("token_budgets_enforced") is not False or not isinstance(checkpoints, list) or not checkpoints:
        return {"applicable": True, "passed": False, "checkpoints": [], "errors": ["actual_model_compaction_checkpoints_required"]}
    workspace_id = connection.execute("SELECT id FROM workspace WHERE singleton=1").fetchone()[0]
    for checkpoint in checkpoints:
        try:
            identity = checkpoint["call_id"]
            require(identity not in identities, "compaction_duplicate_call")
            identities.add(identity)
            attempts = rows(connection, "SELECT * FROM model_budget_attempts WHERE call_id=?", (identity,))
            require(len(attempts) == 1, "compaction_unique_gateway_attempt")
            attempt = attempts[0]
            require(attempt["purpose"] == "context_compaction" and attempt["state"] == "settled" and attempt["workspace_id"] == workspace_id and attempt["quest_id"] is None and attempt["worker_run_id"] is None and all(type(attempt[key]) is int and 0 <= attempt[key] <= attempt[limit] for key, limit in (("input_charged", "input_reserved"), ("output_charged", "output_reserved"))), "compaction_settled_gateway_binding")
            require(checkpoint.get("gateway_attempt") == select(attempt, ("attempt_id", "purpose", "provider_id", "model_id", "state", "input_charged", "output_charged")), "compaction_driver_attempt_binding")
            saved = checkpoint["archive"]
            archive = connection.execute("SELECT * FROM context_archives WHERE id=?", (saved["id"],)).fetchone()
            require(archive is not None and archive["scope"] == "router" and archive["scope_id"] == "main" and timestamp(archive["created_at"]) >= attempt["created_at"], "compaction_archive_order")
            capsule, sources = strict_json(archive["capsule_json"]), strict_json(archive["source_json"])
            require(saved == {"id": archive["id"], "source_hash": archive["source_hash"], "capsule_hash": archive["capsule_hash"], "model_handoff": capsule.get("model_handoff")}, "compaction_checkpoint_archive_binding")
            require(value_sha(capsule) == archive["capsule_hash"] and value_sha(sources) == archive["source_hash"] and capsule.get("model_handoff", {}).get("status") == "unverified", "compaction_checkpoint_hash")
            ids = [row["id"] for row in sources]
            require(checkpoint["source_ids"] == ids and type(checkpoint["source_count"]) is int and checkpoint["source_count"] == len(ids) > 0, "compaction_checkpoint_sources")
            source_ids.extend(ids)
            details.append({"call_id": identity, "archive_id": archive["id"], "known_settled_tokens": attempt["input_charged"] + attempt["output_charged"], "binding_valid": True})
        except (ValueError, TypeError, KeyError) as exc:
            errors.append({"error_type": type(exc).__name__})
    if len(source_ids) != len(set(source_ids)) or compaction.get("source_count") != len(source_ids) or compaction.get("model_handoff") != checkpoints[-1].get("archive", {}).get("model_handoff"):
        errors.append({"code": "compaction_frontier_and_final_handoff"})
    verified = compaction.get("verified_sources", [])
    if [item.get("source_id") for item in verified] != source_ids:
        errors.append({"code": "compaction_exact_readback_inventory"})
    else:
        for item in verified:
            source = connection.execute("SELECT content FROM messages WHERE id=? AND conversation_id='main'", (item["source_id"],)).fetchone()
            if source is None or hashlib.sha256(source[0].encode()).hexdigest() != item.get("content_sha256"):
                errors.append({"code": "compaction_exact_readback_hash"})
    return {"applicable": True, "passed": not errors, "checkpoints": details, "errors": errors}


