def goals_from_draft(draft, live, supplementary, memory_result, source_version):
    """Keep every requirement; promotion requires concrete immutable evidence."""
    original = draft["goals"]
    if len(original) != 15 or {row["number"] for row in original} != set(range(1, 16)):
        raise ValueError("Original 15-goal inventory missing")
    observed_checks = {
        name
        for row in live["current_source_runs"]
        if row["strictly_accepted"]
        for name, status in row["acceptance"].get("checks", {}).items()
        if status == "passed"
    }
    goals = []
    for item in original:
        row = dict(item)
        required = set(item.get("required_strict_checks", []))
        strict = live["all_three_levels_accepted"] and required <= observed_checks
        if item["number"] in SUPPLEMENT_MODES:
            mode = SUPPLEMENT_MODES[item["number"]]
            accepted = supplementary["modes"].get(mode, {}).get("passed") is True
            observation = supplementary["modes"].get(
                mode,
                {"passed": False, "reason": "actual_supplementary_evidence_missing"},
            )
        elif item["number"] == 13:
            accepted, observation = memory_result["passed"], memory_result
        else:
            accepted, observation = (
                strict,
                {
                    "all_three_strict_levels_accepted": live[
                        "all_three_levels_accepted"
                    ],
                    "required_checks_missing_from_accepted_runs": sorted(
                        required - observed_checks
                    ),
                },
            )
        row.update(
            source_version=source_version,
            acceptance_status="satisfied" if accepted else "not_demonstrated",
            independent_observation=observation,
        )
        goals.append(row)
    return goals


