        row.get("origin") != CORE_POLICY
        or not row.get("approved_assignment_valid")
        or not row.get("admission_inventory_complete")
        or row.get("declared_source_count") != row.get("admitted_source_count")
        for row in inventories
    ):
        errors.append("core_approved_source_inventory")
