        "admission_binding_valid",
        "settled_source_valid",
        "no_model_reservation_or_gateway_attempt",
        "complete_user_message_valid",
        "user_message_precedes_first_assistant",
    )
    if any(
        row.get("origin") != CORE_POLICY
        or any(row.get(field) is not True for field in required)
        for row in sources
    ):
        errors.append("core_full_source_evidence")
    counters = report.get("worker_counters", core.get("tool_counters", []))
    if any(
        row.get("tools_exact") is not True
        or row.get("model_selection_bindings_valid") is not True
        or row.get("unattributed_tool_spend") != 0
